2
3    // code goes here
4    return strArr;
5
6  }
7
8  // keep this function call here
9  console.log(MatrixChallenge(readline()));
```

#### Solution:

```javascript
function MatrixChallenge(strArr) {
  const matrix = strArr.map(row =>
    row.replace(/[\(\)]/g, "").split(",").map(Number)
  );

  const N = matrix.length;

  // Copy original matrix
  const closure = matrix.map(row => [...row]);

  // Find all reachable connections
  for (let k = 0; k < N; k++) {
    for (let i = 0; i < N; i++) {
      for (let j = 0; j < N; j++) {
        if (closure[i][k] === 1 && closure[k][j] === 1) {
          closure[i][j] = 1;
        }
      }
    }
  }

  const missingConnections = [];

  // Compare closure with original matrix
  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {

      // ignore self connection
      if (i === j) continue;

      if (closure[i][j] === 1 && matrix[i][j] === 0) {
        missingConnections.push([i, j]);
      }
    }
  }

  if (missingConnections.length === 0) {
    return "transitive";
  }

  missingConnections.sort((a, b) => {
    if (a[0] !== b[0]) {
      return a[0] - b[0];
    }
    return a[1] - b[1];
  });

  return missingConnections
    .map(pair => `(${pair[0]},${pair[1]})`)
    .join("-");
}
```

